package com.ansh.bank; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.client.TestRestTemplate; import org.springframework.boot.test.web.server.LocalServerPort; import org.springframework.http.*; import static org.junit.jupiter.api.Assertions.*;
/** Exercise authentication and protected account HTTP endpoints. */ @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class AuthAccountApiTest{@LocalServerPort int port; @Autowired TestRestTemplate rest; @Test void loginThenFetchAccounts(){var login=rest.postForEntity("http://localhost:"+port+"/api/auth/login",java.util.Map.of("email","demo@ansh.bank","password","demo123"),java.util.Map.class);assertEquals(200,login.getStatusCode().value());var token=(String)login.getBody().get("token");var h=new HttpHeaders();h.setBearerAuth(token);assertTrue(rest.exchange("http://localhost:"+port+"/api/accounts",HttpMethod.GET,new HttpEntity<>(h),String.class).getBody().contains("Everyday account"));}}
